      "activity_id": "A2.1",
      "activity_name": "Design HA architecture for XD-Admin",
      "activity_description": "Design leader election, state replication, and failover mechanisms using ZooKeeper.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A2.2",
      "activity_name": "Implement HA support in XD-Admin",
      "activity_description": "Modify XD-Admin code to support multiple instances, integrate ZooKeeper for coordination.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A2.3",
      "activity_name": "Create/update Ambari service definitions and blueprints",
      "activity_description": "Extend Ambari service definition for XD-Admin to allow multiple instances; create blueprints for HA deployment.",
      "most_likely_effort": 12
