      "most_likely_effort": 4
    },
    {
      "activity_id": "A3.1",
      "activity_name": "Design annotations and programming model",
      "activity_description": "Define @EnableModule, @Input, @Output annotations and their semantics; decide on auto-configuration approach.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A3.2",
      "activity_name": "Implement annotation processors",
      "activity_description": "Create Spring configuration class for @EnableModule; implement BeanFactoryPostProcessor to process @Input/@Output.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A3.3",
      "activity_name": "Implement automatic channel bean creation and adapters",
      "activity_description": "Generate channel beans (DirectChannel, PublishSubscribeChannel, etc.) and corresponding adapters based on annotations.",
      "most_likely_effort": 16
