      "activity_name": "Update developer documentation and samples",
      "activity_description": "Document new programming model, provide example modules using annotations.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A4.1",
      "activity_name": "Complete Kryo optimization code changes",
      "activity_description": "Implement remaining Kryo serializer registrations, buffer pooling, and configuration tweaks.",
      "most_likely_effort": 12
