      "most_likely_effort": 4
    },
    {
      "activity_id": "A5.2",
      "activity_name": "Install and configure Jenkins on EC2",
      "activity_description": "Set up Jenkins master with Docker agent support, configure plugins, credentials, and global settings.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A5.3",
      "activity_name": "Migrate existing build jobs for 1.2.x branch",
